import time, itertools
from reduce import reduce
# All 8 clauses over vars 1,2,3 -> unsatisfiable, but num_vars large.
clauses=[]
for vs in itertools.combinations([1,2,3],3):
    for signs in itertools.product((1,-1),repeat=3):
        clauses.append([s*v for s,v in zip(signs,vs)])
for m in (16,18,20):
    inst={'num_vars':m,'clauses':clauses}
    t0=time.time(); out=reduce(inst); dt=time.time()-t0
    print('m=',m,'time=%.3f'%dt,'out=',out)
""}

